package cn.ybcase.bureau;

import cn.ybcase.bureau.common.BizException;
import cn.ybcase.bureau.repository.CaseCauseRepository;
import cn.ybcase.bureau.service.*;
import cn.ybcase.core.common.ConfigChangedEvent;
import cn.ybcase.core.entity.SysUser;
import cn.ybcase.core.repository.*;
import cn.ybcase.core.security.JwtService;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest @ActiveProfiles("test") @AutoConfigureMockMvc
class InboxFeedbackIntegrationTest {
    @Autowired MockMvc mvc; @Autowired ObjectMapper mapper; @Autowired JdbcTemplate jdbc;
    @Autowired CaseService cases; @Autowired ClueService clues; @Autowired ProcedureService procedure;
    @Autowired OversightService oversight; @Autowired MessageService messages; @Autowired CaseCauseRepository causes; @Autowired BureauConfig config;
    @Autowired SysUserRepository users; @Autowired SysRoleRepository roles; @Autowired JwtService jwt;
    String scope;
    record Actor(String name,String token){}
    Actor actor(String role){var u=new SysUser();u.setUsername("module_"+System.nanoTime());u.setRealName("矩阵"+role);u.setPassword("unused");u.getRoles().add(roles.findByCode(role).orElseThrow());u=users.save(u);return new Actor(u.getUsername(),jwt.issue(u.getUsername(),u.getTokenVersion()));}
    @BeforeEach void self(){FixtureUsers.ensure(jdbc,"foreign-owner","HANDLER");scope=jdbc.queryForObject("select cfg_value from sys_config where cfg_key='case_view_scope'",String.class);jdbc.update("update sys_config set cfg_value='SELF' where cfg_key='case_view_scope'");config.onConfigChanged(new ConfigChangedEvent("case_view_scope"));}
    @AfterEach void restore(){jdbc.update("update sys_config set cfg_value=? where cfg_key='case_view_scope'",scope);config.onConfigChanged(new ConfigChangedEvent("case_view_scope"));}
    long fresh(String owner){long cause=causes.findAll().stream().filter(x->x.getItemNo()==13).findFirst().orElseThrow().getId();return cases.create(new CaseService.CaseCreateReq(null,cause,"SUMMARY","MODULE-"+System.nanoTime(),"PROVIDER",null,null,null,null,"权限边界",BigDecimal.TEN,List.of(new CaseService.OfficerReq("王办案","YB001","LEAD"),new CaseService.OfficerReq("张协办","YB002","MEMBER")),null,null,null,null),owner).getId();}
    long clue(String owner){return clues.create(new ClueService.ClueCreateReq("COMPLAINT","模块范围","医院","PROVIDER",LocalDate.now(),owner),owner).getId();}
    JsonNode call(Actor a,String method,String path,Object body,int code) throws Exception {var req=("GET".equals(method)?get(path):post(path)).header("Authorization","Bearer "+a.token());if(body!=null)req.contentType("application/json").content(mapper.writeValueAsBytes(body));var r=mvc.perform(req).andReturn().getResponse();var json=mapper.readTree(r.getContentAsString());assertEquals(code,json.path("code").asInt(),path+" "+r.getContentAsString());if(code==403)assertTrue(r.getStatus()==200 || r.getStatus()==403, "Role denial must use a supported HTTP envelope");return json.path("data");}
    long inspection(Actor owner){return ((Number)oversight.createInspection(new OversightService.InspectionReq(null,"INSPECT-"+System.nanoTime(),"PROVIDER","甲、乙",LocalDate.now()),owner.name()).get("id")).longValue();}
    long transfer(long clue){procedure.addTransfer(new ProcedureService.TransferReq(clue,null,"IN","移送机关","ADMIN","范围测试",null,null));return jdbc.queryForObject("select max(id) from case_transfer where clue_id=?",Long.class,clue);}
    long message(Actor actor,String link,String dedup){messages.send(actor.name(),"DEADLINE","秘密标题","秘密内容",link,dedup);return jdbc.queryForObject("select max(id) from sys_message where username=?",Long.class,actor.name());}
    @Test void transferredCaseMessagesDisappearFromInboxCountWorkbenchAndReadOperations() throws Exception {var actor=actor("HANDLER");long cid=fresh(actor.name());long id=message(actor,"/case/detail/"+cid,null);assertEquals(1,call(actor,"GET","/api/bureau/messages",null,0).size());jdbc.update("update case_file set owner_user='foreign-owner' where id=?",cid);assertEquals(0,call(actor,"GET","/api/bureau/messages",null,0).size());assertEquals(0,call(actor,"GET","/api/bureau/messages/unread-count",null,0).asInt());assertEquals(0,call(actor,"GET","/api/bureau/my/workbench",null,0).path("unread").asInt());call(actor,"POST","/api/bureau/messages/"+id+"/read",Map.of(),0);call(actor,"POST","/api/bureau/messages/read-all",Map.of(),0);assertNull(jdbc.queryForObject("select read_at from sys_message where id=?",java.sql.Timestamp.class,id));}
    @Test void staleMessagesAreFilteredBeforeInboxLimitAndOtherRecipientsAreNeverMarked() throws Exception {var actor=actor("HANDLER");var other=actor("HANDLER");long foreign=fresh(other.name());long own=message(actor,"/my/feedback",null),otherMsg=message(other,"/my/feedback",null);for(int i=0;i<55;i++)message(actor,"/case/detail/"+foreign,null);var rows=call(actor,"GET","/api/bureau/messages",null,0);assertEquals(1,rows.size());assertEquals(own,rows.get(0).path("id").asLong());call(actor,"POST","/api/bureau/messages/"+otherMsg+"/read",Map.of(),0);call(actor,"POST","/api/bureau/messages/read-all",Map.of(),0);assertNull(jdbc.queryForObject("select read_at from sys_message where id=?",java.sql.Timestamp.class,otherMsg));assertNotNull(jdbc.queryForObject("select read_at from sys_message where id=?",java.sql.Timestamp.class,own));}
    @Test void deletedMalformedAndOversizedCaseLinksFailClosedWhileAllModeAllowsExistingSources() throws Exception {var actor=actor("HANDLER");long foreign=fresh("foreign-owner");message(actor,"/case/detail/"+foreign,null);message(actor,"/case/detail/999999999999999999999999999999999",null);message(actor,"/case/detail/not-a-case",null);assertEquals(0,call(actor,"GET","/api/bureau/messages",null,0).size());jdbc.update("update sys_config set cfg_value='ALL' where cfg_key='case_view_scope'");config.onConfigChanged(new ConfigChangedEvent("case_view_scope"));assertEquals(1,call(actor,"GET","/api/bureau/messages",null,0).size());}
    @Test void clueMessageFollowsAdoptedCaseAndSupervisoryRoleLossHidesAdminNotifications() throws Exception {var actor=actor("HANDLER");long cl=clue(actor.name());message(actor,"/case/clues","CLUE-"+cl+"-2026-10-22");assertEquals(1,call(actor,"GET","/api/bureau/messages",null,0).size());long foreign=fresh("foreign-owner");jdbc.update("update case_file set clue_id=? where id=?",cl,foreign);assertEquals(0,call(actor,"GET","/api/bureau/messages",null,0).size());message(actor,"/system/feedback",null);assertEquals(0,call(actor,"GET","/api/bureau/messages",null,0).size());}
    long feedback(Actor actor) throws Exception{return call(actor,"POST","/api/bureau/feedback",Map.of("kind","BUG","title","权限反馈","content","问题详情","screenshotBase64","AQID"),0).path("id").asLong();}
    @Test void feedbackCloseAndScreenshotRemainOwnerOnlyAndProcessingIsAdminOnly() throws Exception {var owner=actor("HANDLER");var other=actor("LEGAL");var admin=actor("ADMIN");long id=feedback(owner);call(other,"POST","/api/bureau/feedback/"+id+"/handle",Map.of("status","RESOLVED","reply","越权"),403);call(admin,"POST","/api/bureau/feedback/"+id+"/handle",Map.of("status","RESOLVED","reply","已解决"),0);call(other,"POST","/api/bureau/feedback/"+id+"/close",Map.of(),2091);assertEquals(403,mvc.perform(get("/api/bureau/feedback/{id}/screenshot",id).header("Authorization","Bearer "+other.token())).andReturn().getResponse().getStatus());call(owner,"POST","/api/bureau/feedback/"+id+"/close",Map.of(),0);var before=jdbc.queryForMap("select * from feedback where id=?",id);call(admin,"POST","/api/bureau/feedback/"+id+"/handle",Map.of("status","PROCESSING"),2091);assertEquals(mapper.valueToTree(before),mapper.valueToTree(jdbc.queryForMap("select * from feedback where id=?",id)));}
    @Test void malformedFeedbackUsesBusinessErrorsWithoutPersisting(){var actor=actor("HANDLER");assertDoesNotThrow(()->{call(actor,"POST","/api/bureau/feedback",Map.of("title","标题","content","内容"),2090);call(actor,"POST","/api/bureau/feedback",Map.of("kind","BUG","title","标题","content","内容","screenshotBase64","not-base64!!"),2090);});assertEquals(0,jdbc.queryForObject("select count(*) from feedback where username=?",Integer.class,actor.name()));}
    @Test void feedbackCsvQuotesUntrustedUsernameAndEveryMultilineField() throws Exception {var admin=actor("ADMIN");var user=new SysUser();user.setUsername("=formula,\"name\"\r\nnext"+System.nanoTime());user.setRealName("CSV");user.setPassword("unused");user.getRoles().add(roles.findByCode("HANDLER").orElseThrow());user=users.save(user);var actor=new Actor(user.getUsername(),jwt.issue(user.getUsername(),user.getTokenVersion()));feedback(actor);var response=mvc.perform(get("/api/bureau/feedback/export").header("Authorization","Bearer "+admin.token())).andReturn().getResponse();String csv=response.getContentAsString(java.nio.charset.StandardCharsets.UTF_8);assertTrue(csv.contains(cn.ybcase.bureau.common.Csv.cell(user.getUsername())),csv);call(actor,"GET","/api/bureau/feedback/export",null,403);}
    @Test void pendingApplicationAndApprovalMessageStopExposingTransferredCaseReason() throws Exception {var actor=actor("HANDLER");long cid=fresh(actor.name());long approval=jdbc.queryForObject("insert into biz_approval(kind,case_id,reason,applicant) values('SUSPEND',?,'秘密案件理由',?) returning id",Long.class,cid,actor.name());messages.send(actor.name(),"APPROVAL","审批单 #"+approval+"（中止）已批准","秘密意见","/case/approvals",null);assertEquals(1,call(actor,"GET","/api/bureau/my/workbench",null,0).path("myApplications").size());jdbc.update("update case_file set owner_user='foreign-owner' where id=?",cid);assertEquals(0,call(actor,"GET","/api/bureau/my/workbench",null,0).path("myApplications").size());assertEquals(0,call(actor,"GET","/api/bureau/messages",null,0).size());}
    @Test void legitimateMemberKeepsCaseReminderUntilAvoidedWithoutChangingOwnership() throws Exception {var member=actor("HANDLER");long cid=fresh("foreign-owner");long uid=users.findByUsername(member.name()).orElseThrow().getId();jdbc.update("insert into case_officer(case_id,name,cert_no,duty,user_id) values(?,'参办人员',?,'MEMBER',?)",cid,"MEMBER-"+System.nanoTime(),uid);message(member,"/case/detail/"+cid,null);assertEquals(1,call(member,"GET","/api/bureau/messages",null,0).size());jdbc.update("update case_officer set avoided=true where case_id=? and user_id=?",cid,uid);assertEquals(0,call(member,"GET","/api/bureau/messages",null,0).size());}
}
